			"lyrics": "울면 안 돼 울면 안 돼\n안 그래도 얼굴 못생겼는데\n찡그리면 더 못 봐줘요\n\n산타 할아버지도 참고 계신대\n울고 있는 너의 찡그린 얼굴\n더 이상은 못 봐주신대\n\n우는 아이라고 해서 무조건 나쁜 아이인 건 아니겠지만\n하루 종일 우는 너의 얼굴은 정말 보고 있기 힘드네\n\n울면 안 돼 지켜보던 산타 할아버지도\n주먹에 힘을 꽉 주신대\n\n우는 아이라고 해서 무조건 나쁜 아이인 건 아니겠지만\n하루 종일 우는 너의 얼굴은 정말 보고 있기 힘드네\n\n울면 안 돼 울면 안 돼\n지켜보던 산타 할아버지도\n주먹에 힘을 꽉 주신대\n더 이상은 못 봐주신대"
