			"enTitle": "Junky",
			"duration": "2:01",
			"lyrics": "가만 보자 내가 뭣을 하려 했더라\n기억력이 자꾸 깜빡깜빡 거리네\n뿔어버린 라면사리를 입에 넣다가\n고춧가루 한 스푼을 기억해냈네\n\n연예인의 이름 따윈 말할 것 없고\n내가 만든 노래가사도 잊어버리네\n이젠 어디 가서 아는 척도 못하네\n새삼스레 나는 점점 멍청해지네\n\n아니 벌써 이럴 나이는 아니지 않나\n쉴새없이 보고 있는 릴스 때문인가\n릴스보다 지겨우면 쇼츠로 넘어가\n나의 뇌는 점점 매끈매끈해지네\n\n이젠 잠시 폰을 내려놓고 뭐가 됐든 생산적인 짓을 해야지\n이젠 정말 문화가 되었나\n전지구적 세뇌활동 의미없는 프로파간다 챌린지용 댄스음악\n무덤덤한 인종차별 남녀노소 갈라치기 도파민 중독",
