			"lyrics": "새로운 피는 이제 말라버렸고\n누구의 탓이라고 할 수도 없고\n좋은 걸 물려주지 못할 것 같아\n우리의 대는 이제 여서 끝난다\n\n노인의 노인을 위한 노인에 의한 나라가 돼\n연금은 팔십살부터 서바이벌로 지급이 돼\n길에서 젊은일 보면 알아서 빌빌 기어야 돼\n빈집은 자꾸만 늘어 마치 내 이빨 빠지듯이\n\n불편한 현실타령 하다보니까\n누구의 탓도 이젠 아닌 것 같아\n아직도 싸운다면 축하해야지\n싸울 사람이 아직 남아있잖아\n\n노인의 노인을 위한 노인에 의한 나라가 돼\n연금은 팔십살부터 서바이벌로 지급이 돼\n길에서 젊은일 보면 알아서 빌빌 기어야 돼\n빈집은 자꾸만 늘어 마치 내 이빨 빠지듯이",
