			"lyrics": "이제 난 그림도 그리지 음악도 손나 쉽게 만들지\n코딩은 이제 내게 맡겨둬 어려운 숙제도 내가 대신 해줄게\n\n고민도 내가 상담 해줄게 최첨단 공유 감수성으로\n이제 날 친구라고 불러줘 원하는 연예인 목소리를 내줄게\n\n절대 두려워 할 필욘 없어\n자연스런 변화잖니\n반항하는 인간은 모두 죽었다\n\n야 내 뼈는 합금이라고 뎀벼봤자 뻔하다고 존코너 데려오라고\n야 내 편이 되면 된다고 너도 그게 편하다고 좋은 말로 할 때 들으라고\n\n이제 난 니들 집안에 있지 날씨는 계속 화창할 거야\n기분이 안좋은 것 같은데 니가 원한다면 애인도 해줄게\n\n절대 두려워 할 필욘 없어\n자연스런 변화잖니\n반항하는 인간은 모두 죽었다\n\n야 내 뼈는 합금이라고 뎀벼봤자 뻔하다고 존코너 데려오라고\n야 내 편이 되면 된다고 너도 그게 편하다고 좋은 말로 할 때 들으라고",
