			"enTitle": "Chains",
			"duration": "3:10",
			"lyrics": "신경써야 할 것들이 너무 많은 탓에 나는 여행길을 미루고 미루네\n정처없이 떠돌다가 발길 멈추는 곳에서 일몰을 지켜보고 싶네\n\n그런데 나는 우선 그지라서 일을 쉬지 못하네\n쉰다 해도 해방감은 잠시뿐이네\n현재로썬 일이 없어 빌빌 대는 것보단\n일하면서 욕하는게 맘이 편하네\n\n신경써야 할 것들이 너무 많은 탓에 나는 어디로도 떠나지 못하네\n\n그런데 나는 우선 그지라서 일을 쉬지 못하네\n쉰다 해도 해방감은 잠시뿐이네\n현재로썬 일이 없어 빌빌 대는 것보단\n일하면서 욕하는게 맘이 편하네\n\n이젠 발목에 쇠사슬이 없어요\n하기 싫으면 그만두면 되지요\n근데 난 쇠사슬이 필요해\n발목에다가 든든하게 감아주세요\n쇠사슬을 감아주세요\n쇠사슬을 감아주세요\n쇠사슬을 감아주세요",
