			"duration": "3:05",
			"lyrics": "별 거 아닌 일에도 쉽게 화를 낸다\n진짜 큰일에는 더 건조해지면서\n당장 하루하루에 신경질을 내다\n인생은 우중충한 회색빛을 띈다\n\n홧병에는 어떤 약이 잘 듣는지\n뭐에 지쳤는지 삶이 지겨운지\n홧김에 뱉었던 욕을 되새기다\n내 기분 내가 직접 잡치고야 만다\n\n망가진 시곗바늘처럼 하루에 두 번 맞았네 대가리 총\n\n인생은 죽어야만 끝이 나는데 조금은 즐길 수도 있지 않을까\n당장에 화낼 일이 너무 많아서 조금의 행복마저 저축을 했나\n우울한 날을 계속 끌어다 쓰면 노인이 됐을 때는 꽃밭이려나\n\n인생은 죽어야만 끝이 나는데 조금은 즐길 수도 있지 않을까\n당장에 화낼 일이 너무 많아서 조금의 행복마저 저축을 했나\n우울한 날을 계속 끌어다 쓰면 노인이 됐을 때는 꽃밭이려나",
