			"enTitle": "Pimple",
			"duration": "2:07",
			"lyrics": "아 슈밤 존나 아픈 여드름이야 이게 하나도 아니고 몇 개나\n연고라도 발라야지 안 그러면 피부가 터져버릴 것만 같단 말이야\n\n여드름도 때가 있는 법이야\n여드름 막 짜면 안 좋아\n여드름도 때가 있는 법이야\n여드름 익을 때까지 기다려\n\n아니 딱히 내가 뭐 관리를 안 하는 것도 아닌데 말이야\n완전히 농익은 여드름 때문에 얼굴에 손을 못 대\n나이 먹고 나 이렇게 내 이 지랄 같은 여드름\n\n여드름도 때가 있는 법이야\n여드름 막 짜면 안 좋아\n여드름도 때가 있는 법이야\n여드름 익을 때까지 기다려\n\n여드름도 때가 있는 법이야\n여드름 막 짜면 안 좋아\n여드름도 때가 있는 법이야\n여드름 익을 때까지 기다려"
