			"title": "졸업",
			"enTitle": "Graduation",
			"isLead": true,
			"duration": "1:42",
			"lyrics": "조금만 더 힘내보자 저 앞의 끝을 향해서 지금까지 잘해왔잖아\n조금만 더 버텨보자 어쨌든 지금보다는 모든게 더 나아질 거야\n\n그 누구도 말해주지 않는 것 한 가지\n졸업 후엔 새로운 졸업이 기다린다\n그래도 뭐 이미 한 번 넘어본 고비는\n아무래도 조금은 더 쉽지 않으려나\n\n초중고를 총 12년 마침내 성인이 되면 비로소 넌 자유로울까\n재수하고 전역하고 어쩌면 휴학도 하고 대졸이면 자유로울까\n\n어찌어찌 먹고 살길을 찾고 삼십년 뒤 퇴직하면 자유일까\n\n그 누구도 말해주지 않는 것 한 가지\n졸업 후엔 새로운 졸업이 기다린다\n그래도 뭐 이미 한 번 넘어본 고비는\n아무래도 조금은 더 쉽지 않으려나\n\n그 누구도 말해주지 않는 것 한 가지\n졸업 후엔 새로운 졸업이 기다린다\n그래도 뭐 이미 한 번 넘어본 고비는\n아무래도 조금은 더 쉽지 않으려나"
