			"lyrics": "가끔씩은 감기에 걸려줘야해\n엄청 아픈 독감 뭐 이런거 말고\n가볍게 콧물을 훌쩍 거리고\n열 때문에 두통이 살짝 있는 감기\n\n그래야 돼 그래야 맘 편히 쉬어\n쉬는 날도 뭔가 해야할 것 같은\n강박에 늦잠도 제대로 못자\n아파야 돼 그래야 마음 편히 쉬어\n\n엄연한 환자입니다 침대 밖으론 안 나가요\n타이레놀 먹습니다 어지러워서 잠 좀 자요\n연락은 하지 마세요\n\n휴식을 위해선 티켓이 필요해 내 스스로 납득 가능한\n어쩌다 한 번씩 감기에 걸려야 마음 편히 쉬어갈텐데\n\n휴식을 위해선 티켓이 필요해 내 스스로 납득 가능한\n어쩌다 한 번씩 감기에 걸려야 마음 편히 쉬어갈텐데\n\n휴식을 위해선 티켓이 필요해 내 스스로 납득 가능한\n어쩌다 한 번씩 감기에 걸려야 마음 편히 쉬어갈텐데\n\n휴식을 위해선 티켓이 필요해 내 스스로 납득 가능한\n어쩌다 한 번씩 감기에 걸려야 마음 편히 쉬어갈텐데"
