			"lyrics": "07. 암막커튼2\n\n하루 종일 잠을 자네요 딱히 할 일이 없어서\n시계 빼떠리를 뺐어요 째깍거리는 게 싫어서\n\n암막커튼 뒤로 희미한 햇살\n날개뼈 모양으로 꺼진 매트리스가 문득 갑갑해졌어요\n\n이제는 잠에서 깨어나 현실을 살아야지 어른답게\n세상은 참 얄짤 없어라 꾸물꾸물 거리면 밟혀 죽으니\n\n살아있는 척을 해봐요 배꼽 위에 깍지를 껴요\n내장 속에 든 게 없어서 움직임을 느낄 수 없죠\n\n암막 커튼 뒤로 하루가 가요\n난 기쁜 마음으로 이불을 다시 덮다 문든 갑갑해졌어요\n\n이제는 잠에서 깨어나 현실을 살아야지 어른답게\n세상은 참 얄짤 없어라 꾸물꾸물 거리면 밟혀 죽으니",
