			"title": "멸망",
			"enTitle": "Fall",
			"duration": "4:07",
			"lyrics": "결국에 세상은 망하고\n우린 모두 죽고 말겠지\n수많은 고통과 기쁨도\n한 줌의 가루가 되겠지\n울창한 도시의 빌딩도\n언젠가는 가라앉겠지\n피곤한 퇴근길 도로도\n텅 빈 채로 남아있겠지\n거대한 화산이 폭팔하든 아님\n운석이라도 떨어지겠지\n아님 화가나서 서로에게\n다시 폭탄이라도 터뜨리겠지\n뭐가 됐든 결국 남는 것은\n아무것도 없겠지 그러니 괜찮아\n잊고 싶은 기억은 모두\n갈림길에 두고 오세요\n가만 보면 사람들도 참\n쓸데없이 감상적이야\n모든 것이 끝날 때에도\n굳이 눈물을 챙겨가니까\n미안하단 말 한마디도\n못 하고선 이제와서 왜\n셀 수 없는 시간이 흘러\n우리의 무대는 끝나고\n그림자만 남았을 때도\n추억하는 이가 있을까\n모든 것엔 끝이 있기에\n아름답다고는 하지만\n끝이 언젠진 모르기에\n가장 추한 얼굴을 하지\n거대한 파도가 도시를 삼키고\n물고기들은 춤을 추겠지\n아님 파란 별이 두 쪽으로\n쪼개질 만큼 큰 지진이 나겠지\n뭐가 됐든 결국 남는 것은\n아무것도 없겠지 그러니 괜찮아\n잊고 싶은 기억은 모두\n갈림길에 두고 오세요\n가만 보면 사람들도 참\n쓸데없이 감상적이야\n모든 것이 끝날 때에도\n굳이 눈물을 챙겨가니까\n미안하단 말 한마디도\n못 하고선 이제와서 왜",
