			"title": "다리에서요",
			"enTitle": "On The Bridge",
			"duration": "3:29",
			"lyrics": "비가 오려는지 어둡네요\n우산 들고 산책갈까 했죠\n집에만 있다가는\n우울해질 것 같아서 말예요\n사람들은 보이지 않네요\n멀리서 천둥이 치나 봐요\n몇 대 없는 차들도 서둘러\n집으로 돌아가네요\n우리는 생각보다 더\n남한테 관심이 없죠\n뭐 나쁘단 건 아니지만 저는\n다리를 건너다가 문득 걸음을 멈췄죠\n다리 밑에서 누군가 울고 있어요\n어린아이도 아닌데\n엄마를 찾고 있네요\n바지 밑에는 새하얀 맨발이에요\n잃어버린 신발 땜에\n많이 속상한가 봐요\n뭐 나쁘단 건 아니지만\n저는 다리를 건너다가\n문득 걸음을 멈췄죠\n다리 밑에서 누군가 울고 있어요\n어린아이도 아닌데\n엄마를 찾고 있네요\n바지 밑에는 새하얀 맨발이에요\n잃어버린 신발 땜에\n많이 속상한가 봐요\n잃어버린 신발 땜에\n많이 속상한가 봐요"
