		"TRK_EP02_001": {
			"id": "TRK_EP02_001",
			"title": "내 마음 속 작은 고블린",
			"enTitle": "Little Goblin",
			"duration": "1:58",
			"lyrics": "쉴 때는 좀 쉬고 늦잠도 자고 낮잠도 자고\n머리를 비우고 오늘 하루는 버린다 치고 느긋하게만\n\n근데 내 마음속 고블린은 채찍을 들고 쫓아온다네\n초록색 피부 시뻘게져서 거품을 물고 휘두른다네\n\n오후 네시 전에 침대에 누워 휴대폰 켜면\n머리맡에 서서 팔짱을 낀 채 날 노려보는 내 작은 괴물\n\n요즘 내 마음속 고블린은 벌크업하고 거대해졌네\n한 번 채찍에 맞고 나면은 나도 모르게 갓생을 사네\n\n쉬는 꼴 못 보는 내 마음속의 악덕 고블린\n영원히 못 갚을 영혼의 빚을 닦달해 대는 내 사채업자"
		},
		"TRK_EP02_002": {
			"id": "TRK_EP02_002",
			"title": "노스텔지어",
			"enTitle": "Nostalgia",
			"isLead": true,
			"duration": "3:08",
			"lyrics": "기분 좋은 바람이 불어오면 콧잔등이 시큰해지곤 하죠\n오랜 기억들은 냄새를 타고 가끔 날 눈물짓게 하죠\n\n피곤함이 묻은 저녁 발걸음 가로등은 아직 켜지지 않고\n파르스름한 거리를 걷다가 문득 날 혼자 웃게 하죠\n\n설명 할 수 없는 어떤 그리움 노스텔지어는\n설령 오래되어 빛이 바래도 파스텔톤이죠\n\n살아본 적 없는 시대 속에서 애타게 누군갈 찾기도 하고\n어렴풋한 과거의 향취에다 많은 돈을 쓰기도 하죠\n\n빠르게 많은 것이 바뀌지만 어떤 것은 내게 영원하겠죠\n점차 희미해지는 기억에다 나는 많이 기대곤 하죠\n\n설명 할 수 없는 어떤 그리움 노스텔지어는\n설령 오래되어 빛이 바래도 파스텔톤이죠\n\n설명 할 수 없는 어떤 그리움 노스텔지어는\n설령 오래되어 빛이 바래도 파스텔톤이죠"
		},
		"TRK_EP02_003": {
			"id": "TRK_EP02_003",
			"title": "배고파요",
			"enTitle": "Hunger",
			"duration": "3:32",
			"lyrics": "배고파요 배고파요 먹어도\n먹어도 채워지지 않아요\n가슴 가운데 구멍이 났나 봐요\n무엇으로 채워야 할까요\n\n배고파요 배고파요 쓰라린\n뱃속은 뭔갈 원하고 있죠\n안타까운 건 그 퍼즐\n조각은요 오래전에 잃어버렸어요\n\n빈틈 사이는 마모가 되었는지\n다른 조각은 끼울 수가 없죠\n비슷비슷한 상실을 안고\n살아가죠 채워주려는 사람은 없죠\n\n배고파요 배고파요\n주변의 음식을 모두 먹어치워도\n배꼽시계는 멈출 생각이 없죠\n망가진 부품이 있는가 봐요\n\n빈틈 사이는 마모가 되었는지\n다른 톱니바퀼 끼울 수 없죠\n비슷비슷한 고장을\n안고 살아가죠 나눠주려는 사람은 없죠\n"
		},
		"TRK_EP02_004": {
			"id": "TRK_EP02_004",
			"title": "꿈 채무자",
			"enTitle": "I Dreamed a Dream",
			"duration": "2:54",
			"lyrics": "이젠 더 할 일도 또 쉴 것도 다 해치웠군요\n내일도 일하러 또 가려면 일찍 자야겠죠\n그런데 왜인지 오늘 밤은 잠들 수 없죠\n피곤한 두 눈을 끔뻑끔뻑 거리면서도\n시간은 어느새 꽤 늦었죠 나도 자고 싶죠\n\n어느새부턴가 내 잠에는 꿈이 사라졌죠\n어릴 때 꾸었던 꿈을 이제 갚아야 할 때죠\n오로지 충전만을 위한 잠을 자다가\n배터리 수명 다 된 담엔 교체되겠죠\n그런데 세상은 걱정 말라죠 교체 선수는 참 많으니까\n\n이렇게 살다가 가는 가요 그게 맞는 거죠\n내일도 일하고 또 쉬다가 잠을 자야겠죠\n그래서일까요 오늘따라 잠이 무섭죠\n정해진 죽음을 따라가는 연습 같아서\n시간도 어느새 꽤 늦었죠 나도 자고 싶죠"
		},
