			"version": "Live-2023.12.16.",
			"duration": "6:06",
			"lyrics": "사람에 맛이 있다면\n난 좀 싱거운 맛이다\n레시피 대로 했는데\n밍숭맹숭한 맛이다\n\n자극적이지가 않다\n사람이 좀 재미없다\n그래서 그런 것일까\n가끔 남이 좀 부럽다\n\n근데 어째 모기는 나만 쫓아다니나\n사람들은 나더러 꼭 물에 물 탄 것 같다던데\n\n내 피 빨던 모기야 솔직하게 말해줘 무슨 맛이니\n내 피 빨간색이야 국물 색깔만 보면 꼭 매운맛일 것 같아\n\n시중에 판매된다면\n돈 주곤 안 사 먹을걸\n달거나 짜야 되는데\n그냥 심심한 맛이다\n\n영양식이라 하기엔\n양심에 가책이 든다\n영양분이라곤 없다\n그냥 싱거울 뿐이다\n\n근데 어째 모기는 나만 쫓아다니나\n사람들은 나더러 꼭 물에 물 탄 것 같다던데\n\n내 피 빨던 모기야 솔직하게 말해줘 무슨 맛이니\n내 피 빨간색이야 국물 색깔만 보면 꼭 매운맛일 것 같아\n내 피\n\n빨던 모기야 솔직하게 말해줘 무슨 맛이니\n내 피 빨간색이야 국물 색깔만 보면 꼭 매운맛일 것 같아\n\n믿어버렸어 친구놈을 한 번 더, 믿을만한 정보라더니\n모아놨던 돈 수업료로 날리고 묶어놨던 적금을 깼지\n나도 알아 뭐 내가 바보 같은 거, 남들처럼 살고 싶은데\n통장은 비고 반지하는 추운걸 곱등이가 안 나올 때만\n\n괜찮은 사람이랑 오순도순 사는 것도 좋겠지\n괜찮은 사람이 내 룸메이트 바퀴벌레 곱등이랑 돈벌레를 싫어하지 않는다면 말이지\n\n헤이호, 헤이호, 해가 뜨지를 않네. 떴다 해도 내 방에선 안 보이지만\n헤이호, 헤이호, 아름답기는 개뿔, 아프니까 그만 때려 개새끼들아\n\n전화 받아라 사랑하는 친구야, 네가 줬던 정보로 난 빚을 졌단다\n있다 저녁에 한강에서 만나자, 온다 카고 안 나오면 신용불량자\n나도 알아 뭐 내가 바보같은 거 헛짓거리 그만하고 저축해야지\n하고 또 하고 400년 하다보면 28평 아파트를 한 칸 얻겠지\n\n괜찮은 사람이랑 오순도순 사는 것도 좋겠지\n괜찮은 사람이 내 룸메이트 바퀴벌레 곱등이랑 돈벌레를 싫어하지 않는다면 말이지\n\n헤이호, 헤이호, 해가 뜨지를 않네. 떴다 해도 내 방에선 안 보이지만\n헤이호, 헤이호, 아름답기는 개뿔, 아프니까 그만 때려 개새끼들아\n헤이호, 헤이호, 해가 뜨지를 않네. 떴다 해도 내 방에선 안 보이지만\n헤이호, 헤이호, 아름답기는 개뿔, 아프니까 그만 때려 개새끼들아"
