			"duration": "2:42",
			"lyrics": "좆됐다 좆됐어 풀리는 일 하나 없이 꼬였네\n좆됐다 좆됐어 내 맘대로 되는 일이 없구나\n\n내 인생은 내가 주인이라 그러데\n암만 봐도 나는 그냥 노빈데\n어른 말씀 들어두면 떡을 준다메\n떡에 미쳐 환장하는 노친네\n\n이리저리 목줄 채워 끌려다니다\n디스크만 터진 채로 팽을 당하네\n인생살이 좌우지간 고통이지만\n쉼표 한 번 찍고 가면 안 되려나요\n\n좆됐다 좆됐어 풀리는 일 하나 없이 꼬였네\n좆됐다 좆됐어 내 맘대로 되는 일이 없구나\n\n살다보면 한 번쯤은 운수 좋다메\n내 인생은 사는 것도 아닌가\n비가 오면 땅이 굳고 날이 갠다메\n내 인생만 집중호우 중인가\n\n하루종일 앉은 채로 모니털 보다\n후두두둑 빠지는 내 머리털 본다\n인생살이 좌우지간 고통이지만\n쉼표 한 번 찍고 가면 안 되려나요\n\n좆됐다 좆됐어 풀리는 일 하나 없이 꼬였네\n좆됐다 좆됐어 내 맘대로 되는 일이 없구나\n\n좆됐다 좆됐다 좆됐다 좆됐다 좆됐다 좆됐다 좆됐다 좆됐다\n좆됐다 좆됐다 좆됐다 좆됐다 좆됐다 좆됐다 좆됐다 좆됐다\n좆됐다 좆됐다 좆됐다 좆됐다 좆됐다 좆됐다 좆됐다 좆됐다\n좆됐다 좆됐다 좆됐다 좆됐다 좆됐다 좆됐다 좆됐다 좆됐다",
