			"lyrics": "믿어버렸어 친구놈을 한 번 더\n믿을만한 정보라더니\n모아놨던 돈 수업료로 날리고\n묶어놨던 적금을 깼지\n나도 알아 뭐 내가 바보 같은 거\n남들처럼 살고 싶은데\n통장은 비고 반지하는 추운걸\n곱등이가 안 나올 때만\n\n괜찮은 사람이랑 오순도순 사는 것도 좋겠지\n괜찮은 사람이 내 룸메이트 바퀴벌레 곱등이랑\n돈벌레를 싫어하지 않는다면 말이지\n\n헤이호 헤이호 해가 뜨지를 않네\n떴다 해도 내 방에선 안 보이지만\n헤이호 헤이호 아름답기는 개뿔\n아프니까 그만 때려 개새끼들아\n\n전화 받아라 사랑하는 친구야\n네가 줬던 정보로 난 빚을 졌단다\n있다 저녁에 한강에서 만나자\n온다 카고 안 나오면 신용불량자\n나도 알아 뭐 내가 바보 같은 거\n헛짓거리 그만하고 저축해야지\n하고 또 하고 사백년 하다보면\n이십팔평 아파트를 한 칸 얻겠지\n\n괜찮은 사람이랑 오순도순 사는 것도 좋겠지\n괜찮은 사람이 내 룸메이트 바퀴벌레 곱등이랑\n돈벌레를 싫어하지 않는다면 말이지\n\n헤이호 헤이호 해가 뜨지를 않네\n떴다 해도 내 방에선 안 보이지만\n헤이호 헤이호 아름답기는 개뿔\n아프니까 그만 때려 개새끼들아\n\n헤이호 헤이호 해가 뜨지를 않네\n떴다 해도 내 방에선 안 보이지만\n헤이호 헤이호 아름답기는 개뿔\n아프니까 그만 때려 개새끼들아",
