			"lyrics": "우리는 술먹고 토하는 친구들 세상에게 버림받은 악성 종양들\n알코올을 상처입은 가슴에 붓는 효과 빠른 상처소독법\n\n그렇습니다 뭐 자괴감이 드는 것은 분명한 사실이지요\n그래도 어쩌겠습니까 저 따위에게 세상은 기대가 너무 큽니다\n기대가 크면 배신감도 크다는 것을 우린 일찍이 알고 있었죠\n괜찮습니다 적어도 친구들은 영원히 제 곁에 있을 거니까요\n죽음이 우릴 갈라놓을 때까지\n\n우리는 술먹고 토하는 친구들 세상에게 버림받은 악성 종양들\n알코올을 상처입은 가슴에 붓는 효과 빠른 상처소독법\n\n그렇습니다 뭐 자기파괴적이라는게 틀린 말은 아니지요\n그래도 친구들과 함께 마시면 우울한 마음은 좀 적습니다\n어차피 기대에 못미칠거 함께 못미치는게 낫지요\n거 미쳤다고 말씀하진 마십쇼\n당신이 우리에 대해서 뭘 안다고 그러십니까\n죽음이 우릴 갈라놓을 때까지\n\n우리는 술먹고 토하는 친구들 세상에게 버림받은 악성 종양들\n알코올을 상처입은 가슴에 붓는 효과 빠른 상처소독법",
