			"duration": "5:19",
			"lyrics": "시골쥐와 도시쥐 얘기처럼 나도 도시로 가고 싶었어\n알바부터 시작해 노력했지 갚을 빚이 조금 있었거든\n\n그런데 웬걸 일을 하면 할수록 몸은 망가지고 빚은 더 느네\n일을 마치고 돌아오는 길에 걸레짝 같던 운동화가 생을 다 했네\n\n다리 밑에서 본 사람들은\n전부 언제든 돌아갈 곳이 있는데\n길을 잃은 나는 시궁창에서\n맨발을 담그고 있네\n비가 내리면서 사람들은\n모두 자기들 집으로 돌아가는데\n길을 잃은 나는 시궁창에서\n엄마를 부르고 있네\n\n어미 쥐가 아프단 얘기에도 나는 선뜻 돌아가지 못했어\n도시쥐를 꿈꾸며 떠나온 난 시골쥐도 도시쥐도 아닌 시궁쥐\n\n다리 위에 빛나는 저 도시에 내 자리가 하나 없단 사실도\n손에 박힌 굳은 살처럼 무감각해진 줄 알았어 다섯 살 애처럼 울기 전까지\n\n다리 밑에서 본 사람들은\n전부 언제든 돌아갈 곳이 있는데\n길을 잃은 나는 시궁창에서\n맨발을 담그고 있네\n비가 내리면서 사람들은\n모두 자기들 집으로 돌아가는데\n길을 잃은 나는 시궁창에서\n엄마를 부르고 있네",
