			"lyrics": "푹푹 찌는 열기에 정신은 흐릿하고 턱턱 막히는 숨에 시계만 바라보네\n이미 지난 일들에 묶인 어느밤처럼 시시껄렁하지만 우린 사뭇 진지해\n\n내가 될 수 있었던 많은 사람들 중에 이게 최선이라서 어린 내게 미안해\n\n잡생각은 멈춰 거기까지만\n우린 뇌에 반도 못 쓴다지만\n이제부턴 반에 반만 써보자\n아니면 반에 반에 반에 반만\n\n익숙한 멜로디와 감이 안 오는 가사\n더운 여름날에는 그런 노랠 부를래\n조금 변주 주다가 다시 평범해지는\n너도 나도 조금씩 머릴 비울 이 노래\n\n늦잠으로 다져진 자기혐오보다도 당장 고픈 배부터 뭔갈 채우고 보자\n우린 두 팔을 뻗고 주방으로 가다가 그마저도 힘든지 누워 어플을 켜네\n\n요즘 영화에서는 좀비도 막 뛰던데 더운 날씨 탓이야 여름 때문인 거야\n\n잡생각은 멈춰 거기까지만\n우린 뇌에 반도 못 쓴다지만\n이제부턴 반에 반만 써보자\n아니면 반에 반에 반에 반만\n\n익숙한 멜로디와 감이 안 오는 가사\n더운 여름날에는 그런 노랠 부를래\n조금 변주 주다가 다시 평범해지는\n너도 나도 조금씩 머릴 비울 이 기타",
