			"duration": "3:45",
			"lyrics": "이정도면 됐다 이제 집에 가자\n집에 가서 샤워하고 잠 좀 자자\n오 너무 많은 일이 있었어\n휴대폰은 충전기로 나는 집으로\n\n집에 가는 길을 왜 이렇게 멀까\n다른 말로 나는 너무 멀리 왔나\n오 어서 집에 가고 싶은데\n근데 환승 세 번에다 따릉이도 타야 되네\n\n지하철은 좁디 좁고 사람들은 너무 많고\n의자 수는 별로 없고 내리는 사람은 적고\n앞사람의 입김에선 돼지고기 냄새 나고\n마늘쌈을 싸먹었나 속트름만 주구장창 하네\n피할 길이 없구나\n매일 같이 다짐한다 돈 벌어서 택시타자\n\n따릉이를 타고 이제 집에 가자\n역에서 멀수록 조금 싸지니까\n오 나는 대략 이십분 정도\n그래도 괜찮아 나는 집에 가는 중이니까\n\n슈디두밥바 슈비두밥바 슈비두밥바 슈비두밥바\n집에 가는 길은 너무 즐거우니까\n슈디두밥바 슈비두밥바 슈비두밥바 슈비두밥바\n집에 가는 길은 너무 즐거우니까",
