			"duration": "2:15",
			"lyrics": "그래 뭐가 됐든 결국 지나간다\n칼에 맞은 데도 새살이 또 난다\n과몰입하면은 결국 니가 진다\n눈을 뜨고 상처가 아무는 걸 지켜봐\n\n몸만 성하면은 다시 일어난다\n적어도 니 순대는 뱃속에 있다\n아픔은 잠깐 흉터는 영원하다\n울지마라 칼빵은 많은게 멋이니까\n\n너가 어떤 사람이든 상관없다\n누군가는 너를 싫어할테니까\n엄마 아빠 어딨냐고 물어보면\n가정교육은 독학했다고 해라\n\n너가 어떤 사람이든 상관없다\n누군가는 너를 사랑할테니까\n친구들이 괜찮냐고 물어보면\n델꼬 나가 술값 니가 한 번 내라\n\n그래 뭐가 됐든 결국 지나간다\n칼에 한 번 맞았다고 울지마라\n사람들은 약한 모습을 원한다\n눈을 뜨고 적들을 향해 소릴 질러봐",
