			"duration": "2:40",
			"lyrics": "아니 벌써 세 시간째 도무지 집중이 안 돼\n하기 싫은 공부 돈 내면서 하려는데\n아니 진짜 억울한게 핸드폰도 꺼놨는데\n몇 시간째 같은 페이지에 머무는데\n\n이러면 차라리 집에나 있을걸\n시간과 돈낭비 오늘은 영 아닌듯\n\n옆자리 아저씨 담배 냄새 때문인 것 같기도\n맞은 편 친구의 볼펜 소리 때문인 것 같기도\n아니면 저 멀리 다리 떠는 여자 때문인 건가\n어쨌든 오늘은 스카에서 공부는 아닌 것 같아\n\n이러면 차라리 집에나 있을걸\n시간과 돈낭비 오늘은 영 아닌듯\n\n옆자리 아저씨 담배 냄새 때문인 것 같기도\n맞은 편 친구의 볼펜소리 때문인 것 같기도\n아니면 저 멀리 다리 떠는 여자 때문인 건가\n어쨌든 오늘은 스카에서 공부는 아닌 것 같아",
