			"lyrics": "오늘은 왜 또 숙제를 안 했니\n학원 숙제 하느라고 못했습니다\n학원이 그리 좋은가 봅니다\n학원 가서 살지 학교는 왜 옵니까\n\n그놈의 인스타 좀 지워버려라\n학폭의 반은 마크 주커버그다\n진짜 세상은 화면 밖에 있단다\n뭐가 그리 재밌다고 맨날 쳐다봐\n\n이번 방학엔 공부 좀 해라\n이 썩을 놈의 쉐키들 언제쯤 철이들까\n정신 차려라 한 번에 훅가\n이미 엎질러진 물에다 코박고 죽고 싶냐\n\n오늘은 왜 또 하루 종일 자니\n밤 새 게임 하느라고 못 잤습니다\n게임이 그리 좋은가 봅니다\n인생이란 게임에선 지고 있는데\n\n그놈의 인스타 좀 지워버려라\n학폭의 반은 마크 주커버그다\n진짜 세상은 화면 밖에 있단다\n뭐가 그리 재밌다고 맨날 쳐다봐\n\n이번 방학엔 공부 좀 해라 이 썩을 놈의 쉐키들 언제쯤 철이들까\n정신 차려라 한 번에 훅가 이미 엎질러진 물에다 코박고 죽고 싶냐\n\n이번 방학엔 공부 좀 해라 이 썩을 놈의 쉐키들 언제쯤 철이들까\n정신 차려라 한 번에 훅가 이미 엎질러진 물에다 코박고 죽고 싶냐",
