				"chords": "C Em Bb GF G C Am\nC                                Em            Bb                  G\n   어쩌면 나는 쓸모 없는 그런 사람이 되어가는가 봐\n   아니면 나는 도대체 왜 끊임이 없이 나를 미워할까\n\nF         G                 C             Am\n    어른들은 말해 다 한순간의 방황이라고\n    자라는 와중에 다 겪게 되는 마음이라고\n    어른이 되면은 이 때를 추억하게 된다고\nF             G\n    그런데 지금 난\n\nC                              Em              Bb               G\n어쩌면 나는 필요없는 그런 사람이 이미 되었나 봐\n아니면 나는 도대체 왜 끊임이 없이 외로워야 하나",
